parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "supplier_name": { "type": "string", "description": "Legal name of the company that ISSUED the invoice (the seller). Never the customer." },
    "supplier_vat": { "type": "string", "description": "The seller's VAT number exactly as printed, without spaces. Empty string if absent." },
    "invoice_number": { "type": "string", "description": "Invoice number exactly as printed. Empty string if absent." },
    "invoice_date": { "type": "string", "description": "Invoice date as YYYY-MM-DD. Empty string if absent." },
    "due_date": { "type": "string", "description": "Payment due date as YYYY-MM-DD. Empty string if absent." },
    "currency": { "type": "string", "description": "ISO 4217 code, e.g. EUR, GBP, USD." },
    "po_number": { "type": "string", "description": "The customer's purchase order reference (bon de commande, votre commande, PO number). Empty string if there is none." },
    "lines": {
      "type": "array",
      "description": "One entry per invoice line, in the order printed.",
      "items": {
        "type": "object",
        "properties": {
          "sku": { "type": "string", "description": "Product code / reference exactly as printed. Empty string if absent." },
          "description": { "type": "string" },
          "quantity": { "type": "number" },
          "unit_price": { "type": "number", "description": "Unit price excluding VAT, as printed." },
          "line_total": { "type": "number", "description": "Line amount excluding VAT, as printed." }
        },
        "required": ["sku", "description", "quantity", "unit_price", "line_total"]
      }
    },
    "total_ht": { "type": "number", "description": "Total excluding VAT (Total HT / Subtotal), as printed." },
    "total_vat": { "type": "number", "description": "VAT amount (TVA), as printed. 0 for reverse charge or zero-rated." },
    "total_ttc": { "type": "number", "description": "Total to pay including VAT (Total TTC / Net à payer / Amount due), as printed." }
  },
  "required": ["supplier_name", "supplier_vat", "invoice_number", "invoice_date", "due_date", "currency", "po_number", "lines", "total_ht", "total_vat", "total_ttc"]
}

parameters.jsCode:
// Code node "Normalize & validate" (Process workflow) — Mode: Run Once for Each Item
// Input:  the Information Extractor's answer ($json.output) + the file info from the "Start" trigger
// Output: one clean invoice + the list of problems found by plain rules (no AI here).
// Principle: the AI copies what is printed; this code checks it.

const ai = $json.output ?? $json;               // the extractor puts its result in "output"
const start = $('Start').item.json;             // mode, source, source_ref, file_name

// ---------- small helpers ----------
const r2 = (n) => Math.round(n * 100) / 100;                    // round to cents
const txt = (v) => (v === null || v === undefined ? '' : String(v).trim());

// "1 234,56 €" -> 1234.56   |   "€1,234.56" -> 1234.56   |   12.5 -> 12.5
function num(v) {
  if (typeof v === 'number') return v;
  let s = txt(v).replace(/[^\d,.\-]/g, '');                     // keep digits , . -
  if (s === '') return null;
  if (s.includes(',') && s.includes('.')) {
    // the separator that comes last is the decimal one
    s = s.lastIndexOf(',') > s.lastIndexOf('.') ? s.replace(/\./g, '').replace(',', '.') : s.replace(/,/g, '');
  } else if (s.includes(',')) {
    s = s.replace(',', '.');
  }
  const n = Number(s);
  return Number.isFinite(n) ? n : null;
}

// "2026-10-05" stays, "05/10/2026" -> "2026-10-05", anything else -> null
function isoDate(v) {
  const s = txt(v);
  if (/^\d{4}-\d{2}-\d{2}$/.test(s)) return s;
  const m = s.match(/^(\d{1,2})[\/.\-](\d{1,2})[\/.\-](\d{4})$/);
  return m ? `${m[3]}-${m[2].padStart(2, '0')}-${m[1].padStart(2, '0')}` : null;
}

// ---------- 1. normalize ----------
const invoice = {
  mode: String(start.mode || 'live').trim().toLowerCase(),
  source: start.source || '',
  source_ref: start.source_ref || '',
  file_name: start.file_name || '',
  supplier_name: txt(ai.supplier_name),
  supplier_vat: txt(ai.supplier_vat).replace(/\s/g, '').toUpperCase(),
  invoice_number: txt(ai.invoice_number).replace(/\s/g, ''),
  invoice_date: isoDate(ai.invoice_date),
  due_date: isoDate(ai.due_date),
  currency: txt(ai.currency).toUpperCase() || 'EUR',
  po_number: txt(ai.po_number).replace(/\s/g, '').toUpperCase(),
  lines: (ai.lines || []).map((l) => ({
    sku: txt(l.sku).replace(/\s/g, '').toUpperCase(),
    description: txt(l.description),
    quantity: num(l.quantity) ?? 0,
    unit_price: num(l.unit_price) ?? 0,
    line_total: num(l.line_total) ?? 0,
  })),
  total_ht: num(ai.total_ht),
  total_vat: num(ai.total_vat),
  total_ttc: num(ai.total_ttc),
};

// ---------- 2. check ----------
const issues = [];
const add = (code, message) => issues.push({ code, message });

// a) the fields a payment needs
const missing = ['supplier_vat', 'invoice_number', 'invoice_date', 'total_ttc']
  .filter((f) => invoice[f] === null || invoice[f] === '' || invoice[f] === 0);
if (missing.length) add('missing_field', `Missing on the invoice: ${missing.join(', ')}`);

// b) the lines add up to the total before VAT
const linesSum = r2(invoice.lines.reduce((sum, l) => sum + l.line_total, 0));
if (invoice.total_ht !== null && Math.abs(linesSum - invoice.total_ht) > 0.05) {
  add('math_lines', `Lines add up to ${linesSum}, but the total before VAT says ${invoice.total_ht}`);
}

// c) total before VAT + VAT = total to pay
if (invoice.total_ht !== null && invoice.total_vat !== null && invoice.total_ttc !== null) {
  const expected = r2(invoice.total_ht + invoice.total_vat);
  if (Math.abs(expected - invoice.total_ttc) > 0.05) {
    add('math_total', `${invoice.total_ht} + VAT ${invoice.total_vat} = ${expected}, but the invoice asks for ${invoice.total_ttc}`);
  }
}

// d) the VAT rate is one that exists in France (0 = reverse charge or export)
if (invoice.total_ht > 0 && invoice.total_vat !== null) {
  const rate = r2((invoice.total_vat / invoice.total_ht) * 100);
  const allowed = [0, 2.1, 5.5, 10, 20];
  if (!allowed.some((a) => Math.abs(a - rate) < 0.2)) add('vat_rate', `Unusual VAT rate: ${rate}%`);
}

// e) the dates make sense
if (invoice.invoice_date && invoice.due_date && invoice.due_date < invoice.invoice_date) {
  add('dates', `Due date ${invoice.due_date} is before the invoice date ${invoice.invoice_date}`);
}

return { json: { ...invoice, issues } };

// 1. Get the two inputs
const inv = $('Normalize & validate').item.json;          // the invoice the AI read and the code cleaned
const { supplier, po, po_lines, existing_count } = $json; // what Lookup found in the database

// 2. Start from the problems already found, and make a helper to add new ones
const issues = [...inv.issues];
const add = (code, message) => issues.push({ code, message });

// TODO 1: the supplier must be in our supplier list
if (!supplier) {
  add('unknown_supplier', `Supplier ${inv.supplier_name || inv.supplier_vat} is not in the supplier list`);
}

// TODO 2: there must be a purchase order
if (!po) {
  add('po_not_found', inv.po_number ? `PO ${inv.po_number} does not exist` : 'No PO reference on the invoice');
} else {
  // TODO 3: the PO must belong to this supplier and still be open
  if (supplier && po.supplier_id !== supplier.id) {
    add('po_supplier_mismatch', `PO ${po.po_number} belongs to another supplier`);
  }
  if (po.status !== 'open') {
    add('po_closed', `PO ${po.po_number} is ${po.status}`);
  }

  // TODO 4: check every invoice line against the PO line with the same product code
  for (const line of inv.lines) {
    const poLine = po_lines.find((p) => p.sku.toUpperCase() === line.sku);

    if (!poLine) {
      add('line_not_on_po', `${line.sku} is not on PO ${po.po_number}`);
      continue;   // nothing to compare, go to the next line
    }
    if (line.quantity > Number(poLine.qty)) {
      add('qty_above_po', `${line.sku}: ${line.quantity} billed, ${Number(poLine.qty)} ordered`);
    }
    if (line.unit_price > Number(poLine.unit_price) * 1.02) {
      add('price_above_po', `${line.sku}: billed ${line.unit_price} each, agreed ${Number(poLine.unit_price)}`);
    }
  }
}

// 3. Send the invoice on, with the supplier id and the full list of problems
return {
  json: {
    ...inv,
    supplier_id: supplier ? supplier.id : null,
    existing_count: Number(existing_count) || 0,
    issues,
  },
};

// The company's approval policy, in code
const APPROVAL_LIMIT = 1500;   // above this total, a manager must sign

const inv = $json;             // the invoice coming from Match PO
const issues = [...inv.issues];
let status;                    // "let" instead of "const": the value is decided below

// Rule 1: already received → duplicate, and stop there (a duplicate is never paid)
if (inv.existing_count > 0) {
  status = 'duplicate';
  issues.push({ code: 'duplicate', message: `Already received: ${inv.invoice_number} from ${inv.supplier_name}` });
} else {
  // Rule 2: big invoices always need a human
  if (inv.total_ttc > APPROVAL_LIMIT) {
    issues.push({ code: 'above_approval_limit', message: `${inv.total_ttc} ${inv.currency} is above the ${APPROVAL_LIMIT} limit: a manager signs it` });
  }
  // Rules 3 and 4: any problem → a human looks; no problem → approved automatically
  status = issues.length > 0 ? 'needs_review' : 'auto_approved';
}

return {
  json: {
    ...inv,
    issues,
    status,
    decided_by: status === 'auto_approved' ? 'rules' : null,
  },
};
